import re
from contextlib import AbstractContextManager
from typing import BinaryIO, Protocol

# Keys are always generated by the server (never from user filenames); this pattern is a
# second line of defence against path traversal.
_KEY_RE = re.compile(r"^[a-z0-9][a-z0-9_.-]*(/[a-z0-9][a-z0-9_.-]*)*$")


class InvalidStorageKey(ValueError):
    pass


def validate_key(key: str) -> str:
    if not _KEY_RE.fullmatch(key) or ".." in key:
        raise InvalidStorageKey(key)
    return key


class StorageBackend(Protocol):
    def open_write(self, key: str) -> AbstractContextManager[BinaryIO]:
        """Write to a temporary file; the key appears atomically only if the block exits cleanly."""
        ...

    def open_read(self, key: str) -> AbstractContextManager[BinaryIO]: ...

    def move(self, src: str, dst: str) -> None:
        """Atomically rename within the backend (used to promote uploads from tmp/)."""
        ...

    def exists(self, key: str) -> bool: ...

    def size(self, key: str) -> int: ...

    def delete(self, key: str) -> None:
        """Delete if present; missing keys are not an error."""
        ...
